('112.4.b.13.D',3,'Which shows a butterfly life cycle in order?','["egg, caterpillar, chrysalis, butterfly", "caterpillar, egg, butterfly, chrysalis", "egg, butterfly, caterpillar, chrysalis", "chrysalis, egg, caterpillar, butterfly"]'::jsonb,0,'A butterfly goes from egg to caterpillar to chrysalis to adult.','original'),
