('112.4.b.13.D',2,'Does a caterpillar look like its parent butterfly?','["yes, they both have wings", "yes, they look the same", "yes, both can fly", "no, it looks very different"]'::jsonb,3,'A caterpillar looks very different from a butterfly.','original'),
('112.4.b.13.D',3,'A butterfly lays an egg on a leaf. What hatches from the egg?','["a caterpillar", "a frog", "a chick", "a seed"]'::jsonb,0,'A caterpillar hatches from a butterfly egg.','original'),
('112.4.b.13.D',4,'Which animal has young that do NOT look like their parents?','["a dog", "a frog", "a cat", "a horse"]'::jsonb,1,'A tadpole does not look like an adult frog.','original')
) as v(code, diff, prompt, choices, ans, expl, src)
